const LEVEL_CASE_SCHEDULE = Object.freeze(Object.fromEntries(
  Array.from({ length: 49 }, (_, index) => {
    const level = index + 2;
    const caseType = level % 10 === 0 ? "gold" : level % 5 === 0 ? "sweet" : "small";
    return [level, caseType];
  })
));

